layer.css:
@import url("https://fonts.googleapis.com/css2?family=EB+Garamond&family=Noto+Sans+JP:wght@400;700&family=Work+Sans:wght@400;700&display=swap");
[data-ryt="footer"] { color: rgb(0, 0, 0); background-color: var(--ryt-bg); font-style: normal; letter-spacing: 0.96px; text-transform: none }
[data-ryt="brand"] { color: rgb(0, 0, 0); border-radius: 0px; font-family: var(--ryt-font-body); font-size: 14px; font-weight: 400; font-style: italic; line-height: 1.429; letter-spacing: 0.2px; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(0, 0, 0); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
